{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MAPLEMONK.BUILDSKILL_DB_FLIPKART_PRODUCT_LEVEL AS WITH sku_map AS ( SELECT * FROM `maplemonk.Buildskill_GS_SKU_MASTER` QUALIFY ROW_NUMBER() OVER (PARTITION BY master_sku) = 1 ), marketing_consolidated AS ( SELECT LOWER(TRIM(channel)) AS channel, DATE(date) AS date, SUM(CAST(spend AS FLOAT64)) AS total_channel_spend FROM `maplemonk.buildskill_wh_MARKETING_CONSOLIDATED` GROUP BY 1,2 ), flipkart_channel_spend AS ( SELECT LOWER(\'flipkart\') AS channel, DATE(date) AS date, SUM(CAST(spend AS FLOAT64)) AS total_channel_spend FROM `maplemonk.Buildskill_flipkart_ads_pla_pca_fact_items` GROUP BY 1,2 ), flipkart_sales AS ( SELECT TRIM(product_id) AS product_id, DATE(order_date) AS date, SUM(IFNULL(line_item_sales,0)) AS sales, SUM(IFNULL(quantity,0)) AS total_quantity FROM `maplemonk.Buildskill_flipkart_fact_items` GROUP BY 1,2 ), flipkart_ads AS ( SELECT a.campaign_name as campaign_name, a.sku_id as product_id, date(a.start_time) as date, SUM(IFNULL(SAFE_CAST(a.Clicks AS INT64), 0)) AS clicks, SUM(0) AS spend, SUM(IFNULL(SAFE_CAST(a.Direct_Units_Sold AS INT64), 0)) AS conversions, SUM(IFNULL(SAFE_CAST(a.Total_Revenue__Rs__ AS FLOAT64), 0)) AS conversion_value FROM `maplemonk.Buildskill_Flipkart_Seller_Portal_Ads_seller_portal_consolidated_fsn_pla` a GROUP BY 1,2,3 union all SELECT a.campaign_name as campaign_name, a.Advertised_FSN_ID as product_id, date(a.start_time) as date, SUM(IFNULL(SAFE_CAST(a.Clicks AS INT64), 0)) AS clicks, SUM(IFNULL(SAFE_CAST(a.Ad_Spend AS FLOAT64), 0)) AS spend, SUM(IFNULL(SAFE_CAST(a.Units_Sold__Direct_ AS INT64), 0)) AS conversions, SUM(IFNULL(SAFE_CAST(a.Direct_Revenue AS FLOAT64), 0)) AS conversion_value FROM `maplemonk.Buildskill_Flipkart_Ads_consolidated_fsn_pla` a GROUP BY 1,2,3 ), flipkart AS ( SELECT CAST(COALESCE(fs.product_id, fa.product_id) AS STRING) AS PRODUCT_ID, COALESCE(fs.date, fa.date) AS DATE, FORMAT_DATE(\'%A\', COALESCE(fs.date, fa.date)) AS DAY_OF_WEEK, EXTRACT(YEAR FROM COALESCE(fs.date, fa.date)) AS YEAR, EXTRACT(MONTH FROM COALESCE(fs.date, fa.date)) AS MONTH, \'FLIPKART\' AS CHANNEL, CAST(NULL AS STRING) AS ACCOUNT, IFNULL(fa.clicks,0) AS CLICKS, IFNULL(fa.spend,0) AS SPEND, IFNULL(fa.conversions,0) AS CONVERSIONS, IFNULL(fa.conversion_value,0) AS CONVERSION_VALUE, IFNULL(fs.sales,0) AS SALES, IFNULL(fs.total_quantity,0) AS TOTAL_QUANTITY, UPPER(TRIM(sm.master_sku)) AS SKU, UPPER(TRIM(sm.PRODUCT_TITLE)) AS product_name, CONCAT(UPPER(TRIM(sm.CATEGORY)), \' \', UPPER(TRIM(sm.SUB_CATEGORY))) AS master_category FROM flipkart_sales fs FULL OUTER JOIN flipkart_ads fa ON TRIM(fs.product_id) = TRIM(fa.product_id) AND date(fs.date) = date(fa.date) LEFT JOIN sku_map sm ON TRIM(LOWER(COALESCE(fs.product_id, fa.product_id))) = TRIM(LOWER(sm.flipkart_fsn)) ), category_monthly_sales AS ( SELECT master_category, DATE_TRUNC(date, MONTH) AS sales_month, SUM(IFNULL(sales,0)) AS monthly_sales, COUNT(DISTINCT product_id) AS asin_count FROM flipkart GROUP BY 1,2 ), category_past_benchmark AS ( SELECT master_category, sales_month, MAX(monthly_sales) OVER ( PARTITION BY master_category ORDER BY sales_month ROWS BETWEEN 11 PRECEDING AND CURRENT ROW ) AS category_benchmark, asin_count FROM category_monthly_sales ), category_monthly_row_count AS ( SELECT master_category, DATE_TRUNC(date, MONTH) AS sales_month, COUNT(*) AS row_count FROM flipkart GROUP BY 1,2 ) SELECT m.*, mcm.owner AS owner, IFNULL(SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL), 0) AS total_product_lvl_spend, IFNULL(CASE WHEN LOWER(m.channel) LIKE \'%flipkart%\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END, 0) AS total_channel_spend, IFNULL(CASE WHEN LOWER(m.channel) LIKE \'%flipkart%\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END, 0) - IFNULL(SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL), 0) AS spend_diff, CASE WHEN (CASE WHEN LOWER(m.channel) = \'flipkart\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END) > SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL) AND SUM(m.conversion_value) OVER (PARTITION BY m.DATE, m.CHANNEL) > 0 THEN ((CASE WHEN LOWER(m.channel) = \'flipkart\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END) - SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL)) * (m.conversion_value / SUM(m.conversion_value) OVER (PARTITION BY m.DATE, m.CHANNEL)) ELSE 0 END AS allocated_spend_diff, CASE WHEN (CASE WHEN LOWER(m.channel) = \'flipkart\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END) > SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL) AND SUM(m.conversion_value) OVER (PARTITION BY m.DATE, m.CHANNEL) > 0 THEN m.SPEND + (((CASE WHEN LOWER(m.channel) = \'flipkart\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END) - SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL)) * (m.conversion_value / SUM(m.conversion_value) OVER (PARTITION BY m.DATE, m.CHANNEL))) ELSE m.SPEND END AS corrected_spend, SAFE_DIVIDE(cpb.category_benchmark, rc.row_count) AS past_benchmark, IFNULL(CAST(REPLACE(st.target, \',\', \'\') AS FLOAT64),0) AS monthly_target FROM flipkart m LEFT JOIN marketing_consolidated mc ON LOWER(TRIM(CAST(m.channel AS STRING))) = LOWER(TRIM(CAST(mc.channel AS STRING))) AND CAST(m.date AS DATE) = CAST(mc.date AS DATE) LEFT JOIN flipkart_channel_spend ac ON LOWER(TRIM(CAST(m.channel AS STRING))) = LOWER(TRIM(CAST(ac.channel AS STRING))) AND CAST(m.date AS DATE) = CAST(ac.date AS DATE) LEFT JOIN category_past_benchmark cpb ON m.master_category = cpb.master_category AND DATE_TRUNC(m.DATE, MONTH) = cpb.sales_month LEFT JOIN category_monthly_row_count rc ON m.master_category = rc.master_category AND DATE_TRUNC(m.date, MONTH) = rc.sales_month LEFT JOIN `maplemonk.Buildskill_GS_SKU_Target` st ON UPPER(TRIM(m.sku)) = UPPER(TRIM(st.sku)) AND UPPER(TRIM(st.month)) = UPPER(FORMAT_DATE(\'%B\', m.date)) LEFT JOIN `maplemonk.Buildskill_GS_Master_Category_Mapping` mcm ON REGEXP_REPLACE(UPPER(TRIM(m.master_category)), r\'\s+\', \'\') = REGEXP_REPLACE(UPPER(TRIM(mcm.master_category)), r\'\s+\', \'\') ; CREATE OR REPLACE TABLE MAPLEMONK.BUILDSKILL_CATEGORY_DAILY_SUMMARY_FLIPKART AS SELECT DATE, DATE_TRUNC(DATE, MONTH) AS month_start, master_category, product_id, product_name, owner, SUM(IFNULL(sales,0)) AS daily_sales, SUM(IFNULL(corrected_spend,0)) AS daily_spend, SUM(IFNULL(conversion_value,0)) AS daily_paid_sales, MAX(IFNULL(past_benchmark,0)) AS past_benchmark, MAX(IFNULL(monthly_target,0)) AS monthly_target, SUM(IFNULL(conversions,0)) AS daily_ad_orders, SUM(IFNULL(total_quantity,0)) AS total_quantity, SUM(IFNULL(clicks,0)) AS daily_clicks FROM MAPLEMONK.BUILDSKILL_DB_FLIPKART_PRODUCT_LEVEL a GROUP BY 1,2,3,4,5,6; CREATE OR REPLACE TABLE MAPLEMONK.BUILDSKILL_CATEGORY_MONTHLY_SUMMARY_FLIPKART AS SELECT owner, month_start, master_category, product_id, product_name, MAX(past_benchmark) AS past_benchmark, MAX(IFNULL(monthly_target,0)) AS monthly_target, SUM(daily_sales) AS total_sales, SUM(daily_spend) AS total_spend, SUM(daily_paid_sales) AS paid_sales, SAFE_DIVIDE(SUM(daily_spend), SUM(daily_sales)) AS tacos, SAFE_DIVIDE(SUM(daily_spend), SUM(daily_paid_sales)) AS acos, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 1 AND 7 THEN daily_sales ELSE 0 END) AS w1_nmv, MAX(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 1 AND 7 THEN daily_sales END) AS w1_trending, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 1 AND 7 THEN daily_spend ELSE 0 END) AS w1_spend, MAX(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 1 AND 7 THEN daily_spend END) AS w1_trending_spend, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 1 AND 7 THEN daily_paid_sales ELSE 0 END) AS w1_paid_sales, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 1 AND 7 THEN total_quantity ELSE 0 END) AS w1_total_quantity, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 8 AND 14 THEN daily_sales ELSE 0 END) AS w2_nmv, MAX(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 8 AND 14 THEN daily_sales END) AS w2_trending, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 8 AND 14 THEN daily_spend ELSE 0 END) AS w2_spend, MAX(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 8 AND 14 THEN daily_spend END) AS w2_trending_spend, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 8 AND 14 THEN daily_paid_sales ELSE 0 END) AS w2_paid_sales, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 8 AND 14 THEN total_quantity ELSE 0 END) AS w2_total_quantity, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 15 AND 21 THEN daily_sales ELSE 0 END) AS w3_nmv, MAX(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 15 AND 21 THEN daily_sales END) AS w3_trending, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 15 AND 21 THEN daily_spend ELSE 0 END) AS w3_spend, MAX(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 15 AND 21 THEN daily_spend END) AS w3_trending_spend, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 15 AND 21 THEN daily_paid_sales ELSE 0 END) AS w3_paid_sales, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 15 AND 21 THEN total_quantity ELSE 0 END) AS w3_total_quantity, SUM(CASE WHEN EXTRACT(DAY FROM DATE) >= 22 THEN daily_sales ELSE 0 END) AS w4_nmv, MAX(CASE WHEN EXTRACT(DAY FROM DATE) >= 22 THEN daily_sales END) AS w4_trending, SUM(CASE WHEN EXTRACT(DAY FROM DATE) >= 22 THEN daily_spend ELSE 0 END) AS w4_spend, MAX(CASE WHEN EXTRACT(DAY FROM DATE) >= 22 THEN daily_spend END) AS w4_trending_spend, SUM(CASE WHEN EXTRACT(DAY FROM DATE) >= 22 THEN daily_paid_sales ELSE 0 END) AS w4_paid_sales, SUM(CASE WHEN EXTRACT(DAY FROM DATE) >= 22 THEN total_quantity ELSE 0 END) AS w4_total_quantity, SUM(daily_ad_orders) AS ad_orders, SUM(total_quantity) AS total_orders, SUM(daily_clicks) AS clicks FROM maplemonk.BUILDSKILL_CATEGORY_DAILY_SUMMARY_FLIPKART GROUP BY 1,2,3,4,5; CREATE OR REPLACE TABLE MAPLEMONK.BUILDSKILL_AVC_DATA_AVAILABILITY_FLIPKART AS SELECT distinct date(order_date) as date FROM `maplemonk.Buildskill_flipkart_fact_items` ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            